import AsyncStorage from "@react-native-async-storage/async-storage";
import type { ChatAttachment } from "./types";

const COMPOSER_DRAFT_KEY = "keating.mobile.composer-drafts.v1";

export interface ComposerDraft {
  text: string;
  attachments: ChatAttachment[];
}

type DraftMap = Record<string, ComposerDraft>;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function normalizeAttachment(value: unknown): ChatAttachment | null {
  if (!isRecord(value)
    || typeof value.id !== "string"
    || (value.kind !== "image" && value.kind !== "document")
    || typeof value.name !== "string"
    || typeof value.mimeType !== "string"
    || typeof value.size !== "number"
    || !Number.isFinite(value.size)
    || value.size <= 0
    || typeof value.uri !== "string"
    || !value.uri.startsWith("file://")) return null;
  return {
    id: value.id,
    kind: value.kind,
    name: value.name,
    mimeType: value.mimeType,
    size: value.size,
    uri: value.uri,
  };
}

export function normalizeComposerDraft(value: unknown): ComposerDraft {
  if (!isRecord(value)) return { text: "", attachments: [] };
  const attachments = Array.isArray(value.attachments)
    ? value.attachments.map(normalizeAttachment).filter((entry): entry is ChatAttachment => entry !== null).slice(0, 4)
    : [];
  return {
    text: typeof value.text === "string" ? value.text.slice(0, 12_000) : "",
    attachments,
  };
}

async function readDraftMap(): Promise<DraftMap> {
  const raw = await AsyncStorage.getItem(COMPOSER_DRAFT_KEY);
  if (!raw) return {};
  const parsed: unknown = JSON.parse(raw);
  if (!isRecord(parsed)) return {};
  return Object.fromEntries(Object.entries(parsed).map(([sessionId, draft]) => [sessionId, normalizeComposerDraft(draft)]));
}

export async function loadComposerDraft(sessionId: string): Promise<ComposerDraft> {
  return (await readDraftMap())[sessionId] ?? { text: "", attachments: [] };
}

export async function saveComposerDraft(sessionId: string, draft: ComposerDraft): Promise<void> {
  const drafts = await readDraftMap();
  const normalized = normalizeComposerDraft(draft);
  if (!normalized.text && normalized.attachments.length === 0) delete drafts[sessionId];
  else drafts[sessionId] = normalized;
  await AsyncStorage.setItem(COMPOSER_DRAFT_KEY, JSON.stringify(drafts));
}

export async function clearComposerDraft(sessionId: string): Promise<void> {
  const drafts = await readDraftMap();
  if (!(sessionId in drafts)) return;
  delete drafts[sessionId];
  await AsyncStorage.setItem(COMPOSER_DRAFT_KEY, JSON.stringify(drafts));
}

